WITH eligible AS (SELECT s.* FROM customers s WHERE NOT EXISTS (SELECT 1 FROM sessions ch WHERE ch.customer_id = s.id AND ch.started_at >= s.signup_date)) SELECT id, name, country, segment, age, CASE WHEN name RLIKE '^(Alice Wong|Grace Kim)$' THEN 'PRIORITY' WHEN name RLIKE '^(bob smith|  Carol Diaz)$' THEN 'EXTENDED' ELSE 'GROUP_B' END AS name_zone FROM eligible ORDER BY id DESC NULLS FIRST
